		// also removes all "\r" because Windows.
		for _, ch := range lineText[len(paddingToStrip):] {
			if ch != '\r' {
				out.WriteRune(ch)
			}
		}
		out.WriteByte('\n')
	}

	// Remove the trailing newline from the loop
	result := out.String()
	if len(result) > 0 && result[len(result)-1] == '\n' {
		result = result[:len(result)-1]
